const body = $json.body ?? $json;
const channel = String(body.channel || '').toLowerCase();
const action = String(body.action || 'send').toLowerCase();
const requestId = String(body.request_id || body.requestId || '');
const idempotencyKey = String(body.idempotency_key || body.idempotencyKey || requestId);
const authorized = body.authorization?.authorized === true || body.autonomous_authorized === true;
const dnc = body.dnc === true || body.compliance?.dnc === true;
const recipient = String(body.recipient || body.to || '').trim();
const message = String(body.message || body.body || '').trim();
const subject = String(body.subject || '').trim();

const errors = [];
if (!['sms','email'].includes(channel)) errors.push('channel must be sms or email');
if (!['send','reply'].includes(action)) errors.push('action must be send or reply');
if (!requestId) errors.push('request_id is required');
if (!idempotencyKey) errors.push('idempotency_key is required');
if (!authorized) errors.push('authorization envelope is not approved');
if (dnc) errors.push('DNC suppression is active');
if (!recipient) errors.push('recipient is required');
if (!message) errors.push('message is required');
if (channel === 'email' && !subject && action === 'send') errors.push('subject is required for email send');

return [{ json: {
  ...body,
  channel, action, request_id: requestId, idempotency_key: idempotencyKey,
  authorized, dnc, recipient, message, subject,
  runtime_ready: errors.length === 0,
  validation_errors: errors
} }];

const base = String($env.AGENTICMAIL_API_URL || '').replace(/\/$/, '');
const apiKey = String($env.AGENTICMAIL_API_KEY || '');
const emailPath = String($env.AGENTICMAIL_EMAIL_SEND_PATH || '/api/agenticmail/mail/send');
const smsPath = String($env.AGENTICMAIL_SMS_SEND_PATH || '');
const channel = $json.channel;
if (!base) throw new Error('AGENTICMAIL_API_URL is not configured at runtime');
if (!apiKey) throw new Error('AGENTICMAIL_API_KEY is not configured at runtime');
if (channel === 'sms' && !smsPath) throw new Error('AGENTICMAIL_SMS_SEND_PATH is not configured for SMS runtime');

const path = channel === 'email' ? emailPath : smsPath;
const payload = channel === 'email'
  ? { to: [$json.recipient], subject: $json.subject, body: $json.message, ...( $json.reply_to ? { replyTo: $json.reply_to } : {} ) }
  : { to: $json.recipient, message: $json.message, ...( $json.from ? { from: $json.from } : {} ) };

return [{ json: { ...$json, transport_url: base + path, transport_payload: payload, transport_headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json', 'Idempotency-Key': $json.idempotency_key } } }];

const status = Number($response.statusCode || 0);
const ok = status >= 200 && status < 300;
const original = $('Build AgenticMail Transport Request').first().json;
return [{ json: {
  status: ok ? 'sent' : 'transport_error',
  provider: 'agenticmail',
  channel: original.channel,
  action: original.action,
  request_id: original.request_id,
  idempotency_key: original.idempotency_key,
  recipient: original.recipient,
  thread_id: original.thread_id || original.conversation_id || null,
  provider_status_code: status,
  provider_response: $json,
  receipt_at: new Date().toISOString()
} }];
